<?php
declare(strict_types=1);
require_once __DIR__.'/config/database.php';require_once __DIR__.'/config/backup_step18.php';require_once __DIR__.'/config/deployment_step19.php';
$error=null;$success=null;$runtime=[];$rows=[];$latest=null;try{$pdo=business_db();deployment_step19_ensure($pdo);backup_step18_ensure($pdo);$user=security_step17_current_user($pdo);$ctx=deployment_step19_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));$result=deployment_step19_offsite_copy_latest($pdo,(int)$user['id']);$success='Offsite copy verified for '.$result['backup_code'].'.';}$runtime=deployment_step19_runtime_checks($pdo);$latest=deployment_step19_latest_verified_backup($pdo,$orgId);$s=$pdo->prepare("SELECT * FROM deployment_offsite_targets WHERE organization_id=? ORDER BY id DESC");$s->execute([$orgId]);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Offsite Backup - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="deployment_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 19 • Offsite Backup</small></span></a><div class="os-top-actions"><a class="os-btn" href="backup_history.php">Backup History</a><a class="os-btn primary" href="deployment_center.php">Deployment</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Recovery</div><nav class="os-nav"><a href="deployment_center.php"><i class="dot"></i>Deployment</a><a href="migration_center.php"><i class="dot"></i>Migration</a><a class="active" href="offsite_backup.php"><i class="dot"></i>Offsite Backup</a><a href="scheduler_center.php"><i class="dot"></i>Scheduler</a><a href="step19_audit.php"><i class="dot"></i>Audit</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">PROVIDER-NEUTRAL OFFSITE COPY</div><h1>Keep a verified recovery copy outside the application server.</h1><p>STEP 19 copies only an already verified STEP 18 encrypted package to a private mounted cloud/NAS path and verifies SHA-256 again after copying. Provider credentials are never stored in the application database.</p><div class="os-status-row"><span class="os-chip <?= !empty($runtime['offsite_path_ready'])?'good':'' ?>"><?= !empty($runtime['offsite_path_ready'])?'OFFSITE PATH READY':'HWC_OFFSITE_PATH PENDING' ?></span><span class="os-chip <?= $latest?'good':'' ?>"><?= $latest?deployment_step19_h($latest['backup_code']):'NO VERIFIED BACKUP' ?></span></div></section><?php if($error):?><div class="pp-alert bad"><?= deployment_step19_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><?= deployment_step19_h($success) ?></div><?php endif;?><section class="s10-grid"><article class="s10-card s10-span-6"><h2>Copy Latest Verified Backup</h2><p>Configure <code>HWC_OFFSITE_PATH</code> on the server to a mounted private destination such as a cloud volume, NAS or encrypted sync folder.</p><form method="post"><input type="hidden" name="csrf" value="<?= deployment_step19_h(security_step17_csrf()) ?>"><button class="os-btn primary" <?= (!$latest||empty($runtime['offsite_path_ready']))?'disabled':'' ?>>Copy + Verify SHA-256</button></form><div class="pp-alert" style="margin-top:14px"><strong>Boundary:</strong> STEP 19 does not invent S3/SFTP credentials. A hosting/provider-specific adapter can be added later; the current filesystem adapter works wherever the provider exposes a private mounted path.</div></article><article class="s10-card s10-span-6"><h2>Target Evidence</h2><div class="s10-list"><?php if(!$rows):?><div class="pp-alert">No offsite target verified yet. This is valid while the project remains local.</div><?php endif;?><?php foreach($rows as $r):?><div class="s10-row"><div><b><?= deployment_step19_h($r['target_name']) ?></b><small><?= deployment_step19_h($r['adapter_type'].' • '.($r['last_tested_at']?:'not tested')) ?></small></div><span class="s10-badge <?= $r['last_status']==='pass'?'':'warn' ?>"><?= deployment_step19_h(strtoupper($r['last_status'])) ?></span></div><?php endforeach;?></div></article></section></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
